import{_ as n,a0 as d,w as p,s as r,ao as l,I as t,x as s,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"DF-SHOW：一个基于老式 DOS 应用的终端文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"DF-SHOW：一个基于老式 DOS 应用的终端文件管理器 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DF-SHOW：一个基于老式 DOS 应用的终端文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DF-SHOW：一个基于老式 DOS 应用的终端文件管理器 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20181029 DF-SHOW - A Terminal File Manager Based On An Old DOS Application","title":"DF-SHOW：一个基于老式 DOS 应用的终端文件管理器","tag":"201908","desc":""},"relativePath":"201908/20181029 DF-SHOW - A Terminal File Manager Based On An Old DOS Application.md","filePath":"[post].md"}'),h={name:"201908/20181029 DF-SHOW - A Terminal File Manager Based On An Old DOS Application.md"};function c(g,e,u,f,k,w){const i=d("Link");return p(),r("div",null,[e[20]||(e[20]=l('<h1 id="df-show-一个基于老式-dos-应用的终端文件管理器" tabindex="-1">DF-SHOW：一个基于老式 DOS 应用的终端文件管理器 <a class="header-anchor" href="#df-show-一个基于老式-dos-应用的终端文件管理器" aria-label="Permalink to “DF-SHOW：一个基于老式 DOS 应用的终端文件管理器”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-720x340.png" alt=""></p><p>如果你曾经使用过老牌的 MS-DOS，你可能已经使用或听说过 DF-EDIT。DF-EDIT，意即 <strong>D</strong>irectory <strong>F</strong>ile <strong>Edit</strong>，它是一个鲜为人知的 DOS 文件管理器，最初由 Larry Kroeker 为 MS-DOS 和 PC-DOS 系统而编写。它用于在 MS-DOS 和 PC-DOS 系统中显示给定目录或文件的内容。今天，我偶然发现了一个名为 DF-SHOW 的类似实用程序（<strong>D</strong>irectory <strong>F</strong>ile <strong>Show</strong>），这是一个类 Unix 操作系统的终端文件管理器。它是鲜为人知的 DF-EDIT 文件管理器的 Unix 重写版本，其基于 1986 年发布的 DF-EDIT 2.3d。DF-SHOW 完全是自由开源的，并在 GPLv3 下发布。</p><p>DF-SHOW 可以：</p><ul><li>列出目录的内容，</li><li>查看文件，</li><li>使用你的默认文件编辑器编辑文件，</li><li>将文件复制到不同位置，</li><li>重命名文件，</li><li>删除文件，</li><li>在 DF-SHOW 界面中创建新目录，</li><li>更新文件权限，所有者和组，</li><li>搜索与搜索词匹配的文件，</li><li>启动可执行文件。</li></ul><h3 id="df-show-用法" tabindex="-1">DF-SHOW 用法 <a class="header-anchor" href="#df-show-用法" aria-label="Permalink to “DF-SHOW 用法”">​</a></h3><p>DF-SHOW 实际上是两个程序的结合，名为 <code>show</code> 和 <code>sf</code>。</p><h4 id="show-命令" tabindex="-1">Show 命令 <a class="header-anchor" href="#show-命令" aria-label="Permalink to “Show 命令”">​</a></h4><p><code>show</code> 程序（类似于 <code>ls</code> 命令）用于显示目录的内容、创建新目录、重命名和删除文件/文件夹、更新权限、搜索文件等。</p><p>要查看目录中的内容列表，请使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ show &lt;directory path&gt;</span></span></code></pre></div><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ show dfshow</span></span></code></pre></div><p>这里，<code>dfshow</code> 是一个目录。如果在未指定目录路径的情况下调用 <code>show</code> 命令，它将显示当前目录的内容。</p><p>这是 DF-SHOW 默认界面的样子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-1.png" alt=""></p><p>如你所见，DF-SHOW 的界面不言自明。</p><p>在顶部栏上，你会看到可用的选项列表，例如复制、删除、编辑、修改等。</p><p>完整的可用选项列表如下：</p><ul><li><code>C</code> opy（复制）</li><li><code>D</code> elete（删除）</li><li><code>E</code> dit（编辑）</li><li><code>H</code> idden（隐藏）</li><li><code>M</code> odify（修改）</li><li><code>Q</code> uit（退出）</li><li><code>R</code> ename（重命名）</li><li><code>S</code> how（显示）</li><li>h <code>U</code> nt（文件内搜索）</li><li>e <code>X</code> ec（执行）</li><li><code>R</code> un command（运行命令）</li><li><code>E</code> dit file（编辑文件）</li><li><code>H</code> elp（帮助）</li><li><code>M</code> ake dir（创建目录）</li><li><code>S</code> how dir（显示目录）</li></ul><p>在每个选项中，有一个字母以大写粗体标记。只需按下该字母即可执行相应的操作。例如，要重命名文件，只需按 <code>R</code> 并键入新名称，然后按回车键重命名所选项目。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-2.png" alt=""></p><p>要显示所有选项或取消操作，只需按 <code>ESC</code> 键即可。</p><p>此外，你将在 DF-SHOW 界面的底部看到一堆功能键，以浏览目录的内容。</p><ul><li><code>UP</code> / <code>DOWN</code> 箭头或 <code>F1</code> / <code>F2</code> - 上下移动（一次一行），</li><li><code>PgUp</code> / <code>PgDn</code> - 一次移动一页，</li><li><code>F3</code> / <code>F4</code> - 立即转到列表的顶部和底部，</li><li><code>F5</code> - 刷新，</li><li><code>F6</code> - 标记/取消标记文件（标记的文件将在它们前面用 <code>*</code> 表示），</li><li><code>F7</code> / <code>F8</code> - 一次性标记/取消标记所有文件，</li><li><code>F9</code> - 按以下顺序对列表排序 - 日期和时间、名称、大小。</li></ul><p>按 <code>h</code> 了解有关 <code>show</code> 命令及其选项的更多详细信息。</p><p>要退出 DF-SHOW，只需按 <code>q</code> 即可。</p><h4 id="sf-命令" tabindex="-1">SF 命令 <a class="header-anchor" href="#sf-命令" aria-label="Permalink to “SF 命令”">​</a></h4><p><code>sf</code> （显示文件）用于显示文件的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sf &lt;file&gt;</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-3.png" alt=""></p><p>按 <code>h</code> 了解更多 <code>sf</code> 命令及其选项。要退出，请按 <code>q</code>。</p><p>想试试看？很好，让我们继续在 Linux 系统上安装 DF-SHOW，如下所述。</p><h3 id="安装-df-show" tabindex="-1">安装 DF-SHOW <a class="header-anchor" href="#安装-df-show" aria-label="Permalink to “安装 DF-SHOW”">​</a></h3>',34)),t("p",null,[e[2]||(e[2]=s("DF-SHOW 在 ",-1)),o(i,{href:"https://aur.archlinux.org/packages/dfshow/"},{default:a(()=>[...e[0]||(e[0]=[s("AUR",-1)])]),_:1}),e[3]||(e[3]=s(" 中可用，因此你可以使用 AUR 程序（如 ",-1)),o(i,{href:"https://www.ostechnix.com/yay-found-yet-another-reliable-aur-helper/"},{default:a(()=>[...e[1]||(e[1]=[s("yay",-1)])]),_:1}),e[4]||(e[4]=s("）在任何基于 Arch 的系统上安装它。",-1))]),e[21]||(e[21]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S dfshow</span></span></code></pre></div><p>在 Ubuntu 及其衍生版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo add-apt-repository ppa:ian-hawdon/dfshow</span></span>
<span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span>$ sudo apt-get install dfshow</span></span></code></pre></div><p>在其他 Linux 发行版上，你可以从源代码编译和构建它，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/roberthawdon/dfshow</span></span>
<span class="line"><span>$ cd dfshow</span></span>
<span class="line"><span>$ ./bootstrap</span></span>
<span class="line"><span>$ ./configure</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><p>DF-SHOW 项目的作者只重写了 DF-EDIT 实用程序的一些应用程序。由于源代码可以在 GitHub 上免费获得，因此你可以添加更多功能、改进代码并提交或修复错误（如果有的话）。它仍处于 beta 阶段，但功能齐全。</p><p>你有没试过吗？如果试过，觉得如何？请在下面的评论部分告诉我们你的体验。</p><p>不管如何，希望这有用。还有更多好东西。敬请关注！</p><hr>`,9)),t("p",null,[e[6]||(e[6]=s("via: ",-1)),o(i,{href:"https://www.ostechnix.com/df-show-a-terminal-file-manager-based-on-an-old-dos-application/"},{default:a(()=>[...e[5]||(e[5]=[s("https://www.ostechnix.com/df-show-a-terminal-file-manager-based-on-an-old-dos-application/",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=s("作者：",-1)),o(i,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...e[7]||(e[7]=[s("SK",-1)])]),_:1}),e[12]||(e[12]=s(" 选题：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[8]||(e[8]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 译者：",-1)),o(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[9]||(e[9]=[s("wxy",-1)])]),_:1}),e[14]||(e[14]=s(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=s("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原创编译，",-1)),o(i,{href:"https://linux.cn/"},{default:a(()=>[...e[16]||(e[16]=[s("Linux中国",-1)])]),_:1}),e[19]||(e[19]=s(" 荣誉推出",-1))])])}const m=n(h,[["render",c]]);export{S as __pageData,m as default};
